import {rateLimit} from 'express-rate-limit';
import {ticketAt,qrState,captureProof,verifyTicket,verifyProof} from './attendance-qr.js';
import {randomUUID,randomBytes,randomInt,createHmac,timingSafeEqual,createHash} from 'node:crypto';
import {z} from 'zod';
import {ensure} from './errors.js';
import {keyFor} from './service.js';
import {QuestionnaireService} from './questionnaires.js';
const identifier=z.string().min(1).max(128),requestId=z.string().regex(/^[a-zA-Z0-9_-]{1,100}$/);
export class AttendanceService {
 constructor(core){this.core=core;this.store=core.store;this.rosters=new QuestionnaireService(core)}
 teacher(user,classId){this.core.role(user,'teacher');return this.core.classAccess(user,classId)}
 get(id){const s=this.store.get('attendance_session',identifier.parse(id));ensure(s,404,'NOT_FOUND','签到场次不存在');return s}
 photo(user,id){const p=this.store.get('attendance_image',identifier.parse(id));ensure(p,404,'NOT_FOUND','图片不存在');return p}
 images(user){this.core.role(user,'admin');return this.store.all('attendance_image').map(({base64,...p})=>p)}
 availableImages(user){this.core.role(user,'teacher');return this.store.all('attendance_image').filter(p=>p.active).map(({base64,...p})=>p)}
 upload(user,raw){this.core.role(user,'admin');const b=z.object({title:z.string().trim().min(1).max(100),mime:z.enum(['image/jpeg','image/png']),base64:z.string().regex(/^[A-Za-z0-9+/]+={0,2}$/).max(1400000)}).strict().parse(raw);const bytes=Buffer.from(b.base64,'base64');ensure(bytes.length>0&&bytes.length<=1048576,400,'IMAGE_SIZE','图片不超过1MB');ensure(b.mime==='image/jpeg'?bytes.subarray(0,3).equals(Buffer.from([255,216,255])):bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])),400,'IMAGE_FORMAT','图片格式无效');const image={...b,id:randomUUID(),active:true,sha256:createHash('sha256').update(bytes).digest('hex'),createdAt:this.core.iso()};this.store.put('attendance_image',image.id,image);const {base64,...result}=image;return result}
 imageState(user,id,raw){this.core.role(user,'admin');const {active}=z.object({active:z.boolean()}).strict().parse(raw);const image=this.photo(user,id);this.store.put('attendance_image',id,{...image,active});return {id,active}}
 create(user,raw){const b=z.object({classId:identifier,imageId:identifier,title:z.string().trim().min(1).max(100),clientRequestId:requestId}).strict().parse(raw);this.teacher(user,b.classId);const identity=keyFor(user.id,b.clientRequestId),digest=createHash('sha256').update(JSON.stringify(b)).digest('hex');return this.store.transaction(()=>{const saved=this.store.get('attendance_create',identity);if(saved){ensure(saved.digest===digest,409,'REQUEST_MISMATCH','请求号已用于其他场次');return this.state(user,saved.id)}ensure(!this.store.all('attendance_session').some(s=>s.classId===b.classId&&s.status==='open'),409,'SESSION_OPEN','该班已有进行中的签到，请先结束');const image=this.photo(user,b.imageId);ensure(image.active,409,'IMAGE_WITHDRAWN','请选择可用图片');const roster=this.rosters.members(user,b.classId);ensure(roster.length>0,409,'EMPTY_CLASS','班级尚无学生');const session={id:randomUUID(),classId:b.classId,imageId:b.imageId,title:b.title,createdBy:user.id,createdAt:this.core.iso(),roster:roster.map((m,index)=>({...m,piece:index})),status:'open',secret:randomBytes(32).toString('base64url'),signed:[]};this.store.put('attendance_session',session.id,session);this.store.put('attendance_create',identity,{id:session.id,digest});return this.state(user,session.id)})}
 ticket(session){return ticketAt(session,this.core.now())}
 state(user,id){const session=this.get(id);this.teacher(user,session.classId);const {secret,...safe}=session;return {...safe,...(session.status==='open'?qrState(session,this.core.now()):{ticket:null,expiresAt:null,qrTickets:[],serverNow:this.core.now()}),complete:session.signed.length===session.roster.length}}
 capture(raw,device){const b=z.object({sessionId:identifier,ticket:z.string().regex(/^[a-zA-Z0-9_.-]+$/).max(300)}).strict().parse(raw),s=this.get(b.sessionId);ensure(s.status==='open',409,'SESSION_CLOSED','本场签到已结束');return captureProof(s,b.ticket,this.core.now(),device)}
 list(user,classId){this.teacher(user,classId);return this.store.all('attendance_session').filter(s=>s.classId===classId).map(({roster,signed,secret,...s})=>({...s,total:roster.length,arrived:signed.length}))}
 close(user,id){return this.store.transaction(()=>{const s=this.get(id);this.teacher(user,s.classId);this.store.put('attendance_session',id,{...s,status:'closed',closedAt:this.core.iso()});return this.state(user,id)})}
 checkin(user,raw,device){this.core.role(user,'student');const b=z.object({sessionId:identifier,ticket:z.string().regex(/^[a-zA-Z0-9_.-]+$/).max(300).optional(),scanProof:z.string().regex(/^[a-zA-Z0-9_.-]+$/).max(300).optional()}).strict().refine(x=>!!x.ticket!==!!x.scanProof).parse(raw);return this.store.transaction(()=>{const s=this.get(b.sessionId);this.core.classAccess(user,s.classId);ensure(s.roster.some(m=>m.studentId===user.id),403,'NOT_IN_SNAPSHOT','不在本场签到名单中，请联系教师');ensure(s.status==='open',409,'SESSION_CLOSED','本场签到已结束');const existing=s.signed.find(x=>x.studentId===user.id);if(existing)return {sessionId:s.id,checkedIn:true,at:existing.at};ensure(b.scanProof?verifyProof(s,b.scanProof,this.core.now(),device):verifyTicket(s,b.ticket,this.core.now()),409,'QR_EXPIRED','签到凭证已过期，请重新扫码');const at=this.core.iso();s.signed.push({studentId:user.id,at});this.store.put('attendance_session',s.id,s);return {sessionId:s.id,checkedIn:true,at}})}
 imageBytes(user,id){const p=this.photo(user,id);if(user.role!=='admin'){this.core.role(user,'teacher');ensure(this.store.all('attendance_session').some(s=>s.imageId===id&&this.core.ownsClass(user,this.core.classRecord(s.classId))),403,'FORBIDDEN','无图片查看权限')}return {mime:p.mime,bytes:Buffer.from(p.base64,'base64')}}
 imageData(user,id){const p=this.photo(user,id);if(user.role!=='admin'){this.core.role(user,'teacher');ensure(p.active||this.store.all('attendance_session').some(s=>s.imageId===id&&this.core.ownsClass(user,this.core.classRecord(s.classId))),403,'FORBIDDEN','无图片查看权限')}return {dataUrl:'data:'+p.mime+';base64,'+p.base64}}
 draw(user,raw){const b=z.object({classId:identifier,sessionId:identifier.optional(),scope:z.enum(['all','signed','absent']),count:z.number().int().min(1).max(20),repeat:z.boolean(),clientRequestId:requestId}).strict().parse(raw);this.teacher(user,b.classId);const rid=keyFor(user.id,b.clientRequestId),digest=createHash('sha256').update(JSON.stringify(b)).digest('hex');return this.store.transaction(()=>{const cached=this.store.get('rollcall_result',rid);if(cached){ensure(cached.digest===digest,409,'REQUEST_MISMATCH','请求号已用于其他点名');return cached.result}const roundId=keyFor(user.id,b.classId),round=this.store.get('rollcall_round',roundId)??{id:randomUUID(),called:[]};let pool=this.rosters.members(user,b.classId);if(b.scope!=='all'){ensure(b.sessionId,400,'SESSION_REQUIRED','请选择签到场次');const session=this.get(b.sessionId);this.teacher(user,session.classId);ensure(session.classId===b.classId,403,'FORBIDDEN','签到场次不属于该班');const signed=new Set(session.signed.map(s=>s.studentId));pool=pool.filter(s=>session.roster.some(m=>m.studentId===s.studentId)&&(b.scope==='signed'?signed.has(s.studentId):!signed.has(s.studentId)))}if(!b.repeat)pool=pool.filter(s=>!round.called.includes(s.studentId));ensure(pool.length>=b.count,409,'INSUFFICIENT_CANDIDATES','候选人数不足，请调整范围或开始新一轮');const selected=[];for(let i=0;i<b.count;i++)selected.push(pool.splice(randomInt(pool.length),1)[0]);const result={id:randomUUID(),classId:b.classId,teacherId:user.id,roundId:round.id,scope:b.scope,students:selected,createdAt:this.core.iso()};this.store.put('rollcall_round',roundId,{...round,called:[...new Set([...round.called,...selected.map(s=>s.studentId)])]});this.store.put('rollcall_result',rid,{digest,result});return result})}
 history(user,classId){this.teacher(user,classId);return this.store.all('rollcall_result').map(r=>r.result).filter(r=>r.classId===classId&&r.teacherId===user.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,50)}
 resetRound(user,classId){this.teacher(user,classId);this.store.put('rollcall_round',keyFor(user.id,classId),{id:randomUUID(),called:[]});return {ok:true}}
}
export function attendanceRoutes(app,core){const service=new AttendanceService(core),ok=(res,data)=>res.json({ok:true,data,requestId:res.locals.requestId}),u=res=>res.locals.user;
 app.get('/api/v1/admin/attendance/images',(_q,r)=>ok(r,service.images(u(r))));app.post('/api/v1/admin/attendance/images',(q,r)=>ok(r,service.upload(u(r),q.body)));app.post('/api/v1/admin/attendance/images/:id/state',(q,r)=>ok(r,service.imageState(u(r),q.params.id,q.body)));
 app.get('/api/v1/core/attendance-images',(_q,r)=>ok(r,service.availableImages(u(r))));
 app.get('/api/v1/core/attendance-image-data/:id',(q,r)=>ok(r,service.imageData(u(r),q.params.id)));
 app.get('/api/v1/core/attendance/images/:id',(q,r)=>{const image=service.imageBytes(u(r),q.params.id);r.setHeader('Content-Type',image.mime);r.setHeader('Cache-Control','private,no-store');r.send(image.bytes)});
 app.get('/api/v1/core/classes/:id/attendance', (q,r)=>ok(r,service.list(u(r),q.params.id)));app.post('/api/v1/core/attendance',(q,r)=>ok(r,service.create(u(r),q.body)));app.get('/api/v1/core/attendance/:id',(q,r)=>ok(r,service.state(u(r),q.params.id)));app.post('/api/v1/core/attendance/:id/close',(q,r)=>ok(r,service.close(u(r),q.params.id)));app.post('/api/v1/core/attendance-checkin',(q,r)=>ok(r,service.checkin(u(r),q.body,scanDevice(q))));
 app.post('/api/v1/core/rollcall',(q,r)=>ok(r,service.draw(u(r),q.body)));app.get('/api/v1/core/classes/:id/rollcall',(q,r)=>ok(r,service.history(u(r),q.params.id)));app.post('/api/v1/core/classes/:id/rollcall/reset',(q,r)=>ok(r,service.resetRound(u(r),q.params.id)));
}

export function attendanceScanRoute(app,core){
 const service=new AttendanceService(core);
 const limiter=rateLimit({windowMs:60000,limit:1200,standardHeaders:'draft-8',legacyHeaders:false,handler:(_q,r)=>r.status(429).json({ok:false,error:{code:'RATE_LIMITED',message:'扫码请求过多，请稍后重试'},requestId:r.locals.requestId})});
 app.post('/api/v1/attendance/scan',limiter,(q,r)=>{const device=scanDevice(q)||randomBytes(32).toString('base64url'),data=service.capture(q.body,device);r.cookie(scanCookieName(q),device,{httpOnly:true,secure:!!q.secure,sameSite:'strict',path:'/',maxAge:12*60*60*1000});return r.json({ok:true,data,requestId:r.locals.requestId})});
}

const scanCookieName=q=>q.secure?'__Host-preclass_scan_device':'preclass_scan_device';
function scanDevice(q){const name=scanCookieName(q),values=(q.headers.cookie||'').split(';').map(x=>x.trim()).filter(x=>x.startsWith(name+'='));if(values.length!==1)return undefined;const value=values[0].slice(name.length+1);return /^[-_A-Za-z0-9]{43}$/.test(value)?value:undefined}
